{}
{"query": {"match": {"product_name": "headphones"}}, "size": 1}
{}
{"query": {"range": {"price": {"gte": 30, "lte": 50}}}}
{% endcapture %}

{% capture step1_python %}


response = client.msearch(
  index = "products",
  body = '''
{}
{"query": {"match": {"product_name": "headphones"}}, "size": 1}
{}
