  "message": "User login successful"
}
-->
{% capture step1_rest %}
POST /logs-demo/_doc?routing=user1
{
  "@timestamp": "2025-05-23T10:00:00Z",
  "user": "user1",
  "message": "User login successful"
}
{% endcapture %}

{% capture step1_python %}


response = client.index(
  index = "logs-demo",
  params = { "routing": "user1" },
  body =   {
    "@timestamp": "2025-05-23T10:00:00Z",
    "user": "user1",
    "message": "User login successful"
  }
)

{% endcapture %}

{% include code-block.html
    rest=step1_rest
    python=step1_python %}
<!-- spec_insert_end -->

