<script type="module">
  document.addEventListener('DOMContentLoaded', () => {
    const menu = document.querySelector('#top .nav-menu-on');
    const button = document.querySelector('#top .menu-button');
    button.addEventListener('click', () => {
        menu.classList.toggle('active');
        button.classList.toggle('active');
    });
  });
  document.addEventListener('DOMContentLoaded', () => {
    function getSubMenu(button) {
        const parentLI = button.closest('li');
        const childUL = parentLI.querySelector('ul');
        return childUL;
    }
    function initializeCustomMenuHeights(button) {
        const childUL = getSubMenu(button);
        const height = childUL?.scrollHeight;
        childUL?.style?.setProperty?.('--expanded-height', `${height}px`);
        childUL?.classList?.add?.('nested-nav--menu__mobile-hidden-collapsed');
    }
    function onNestedNavMenuTransitionEnd(e) {
        const { target } = e;
        if (!target?.hasAttribute?.('expanded')) {
            target?.classList.add('nested-nav--menu__mobile-hidden-collapsed');
        }
    }

    function onToggleButtonClick(e) {
        const visibleClassName = 'opensearch-toggle-button-link__visible';
        const visibleSelector = `.${visibleClassName}`;
        const invisibleClassName = 'opensearch-toggle-button-link__invisible';
        const invisibleSelector = `.${invisibleClassName}`;

        const toggle = e.currentTarget;
        const visibleLink = toggle.querySelector(visibleSelector);
        const invisibleLink = toggle.querySelector(invisibleSelector);
        visibleLink.classList.remove(visibleClassName);
        visibleLink.classList.add(invisibleClassName);
        invisibleLink.classList.remove(invisibleClassName);
        invisibleLink.classList.add(visibleClassName);

        const childUL = getSubMenu(toggle);
        const isAlreadyExpanded = childUL?.getAttribute?.('expanded') ?? false;
        if (childUL.classList.contains('nested-nav--menu__mobile-hidden-collapsed')) {
            childUL?.classList?.remove?.('nested-nav--menu__mobile-hidden-collapsed');
        }
        window.setTimeout(() => childUL?.toggleAttribute?.('expanded'), 60);
    }

    document.querySelector('#top .navigation-container--nested-nav-wrapper--nested-nav')?.addEventListener?.('transitionend', onNestedNavMenuTransitionEnd);
    const topNavigationToggleButtons = document.querySelectorAll('#top .opensearch-toggle-button--wrapper');
    for (let i = 0; i < topNavigationToggleButtons.length; ++i) {
        const button = topNavigationToggleButtons[i];
        initializeCustomMenuHeights(button);
        button.addEventListener('click', onToggleButtonClick);
    }
  });
</script>

{%- comment -%}
This include generates Previous Phase and Next Phase sections for migration phase pages.
It uses the migration scenarios data to determine the flow and relationships.
{%- endcomment -%}

{%- assign current_page_url = page.url | remove: '/index' -%}
{%- assign scenarios = site.data.migration-scenarios.scenarios -%}

{%- comment -%}Find previous phases for each scenario{%- endcomment -%}
{%- assign prev_phase_info = '' | split: '' -%}

{%- for scenario in scenarios -%}
  {%- assign found_current = false -%}
  {%- assign step_number = 0 -%}
  {%- assign prev_step = null -%}
  {%- assign prev_step_number = 0 -%}

  {%- for step in scenario.steps -%}
    {%- assign step_number = step_number | plus: 1 -%}
    {%- assign clean_step_url = step.url | replace: '{{site.url}}{{site.baseurl}}', '' -%}

    {%- if clean_step_url == current_page_url -%}
      {%- assign found_current = true -%}
      {%- if prev_step -%}
        {%- capture prev_phase_data -%}{{ prev_step.url }}|{{ prev_step.title }}|{{ scenario.title }}|{{ prev_step_number }}{%- endcapture -%}
        {%- assign prev_phase_info = prev_phase_info | push: prev_phase_data -%}
      {%- endif -%}
      {%- break -%}
    {%- endif -%}

    {%- comment -%}Check substeps too{%- endcomment -%}
    {%- if step.substeps -%}
      {%- for substep in step.substeps -%}
        {%- assign clean_substep_url = substep.url | replace: '{{site.url}}{{site.baseurl}}', '' -%}
        {%- if clean_substep_url == current_page_url -%}
          {%- assign found_current = true -%}
          {%- capture prev_phase_data -%}{{ step.url }}|{{ step.title }}|{{ scenario.title }}|{{ step_number }}{%- endcapture -%}
          {%- assign prev_phase_info = prev_phase_info | push: prev_phase_data -%}
          {%- break -%}
        {%- endif -%}
      {%- endfor -%}
      {%- if found_current -%}
        {%- break -%}
      {%- endif -%}
    {%- endif -%}

    {%- assign prev_step = step -%}
    {%- assign prev_step_number = step_number -%}
  {%- endfor -%}
{%- endfor -%}

{%- comment -%}Remove duplicates from prev_phase_info{%- endcomment -%}
{%- assign unique_prev_phases = '' | split: '' -%}
{%- for phase_data in prev_phase_info -%}
  {%- assign phase_parts = phase_data | split: '|' -%}
  {%- assign phase_url = phase_parts[0] -%}
  {%- assign is_duplicate = false -%}

  {%- for unique_phase_data in unique_prev_phases -%}
    {%- assign unique_parts = unique_phase_data | split: '|' -%}
    {%- if unique_parts[0] == phase_url -%}
      {%- assign is_duplicate = true -%}
      {%- break -%}
    {%- endif -%}
  {%- endfor -%}

  {%- unless is_duplicate -%}
    {%- assign unique_prev_phases = unique_prev_phases | push: phase_data -%}
  {%- endunless -%}
{%- endfor -%}

{%- comment -%}Find next phases for each scenario{%- endcomment -%}
{%- assign next_phase_info = '' | split: '' -%}

{%- for scenario in scenarios -%}
  {%- assign step_number = 0 -%}
  {%- assign current_step_index = -1 -%}

  {%- comment -%}Find the index of the current step in this scenario{%- endcomment -%}
  {%- for step in scenario.steps -%}
    {%- assign step_number = step_number | plus: 1 -%}
    {%- assign clean_step_url = step.url | replace: '{{site.url}}{{site.baseurl}}', '' -%}

    {%- comment -%}Check if this step matches the current page{%- endcomment -%}
    {%- if clean_step_url == current_page_url -%}
      {%- assign current_step_index = step_number -%}
    {%- endif -%}

    {%- comment -%}Also check substeps{%- endcomment -%}
    {%- if step.substeps -%}
      {%- for substep in step.substeps -%}
        {%- assign clean_substep_url = substep.url | replace: '{{site.url}}{{site.baseurl}}', '' -%}
        {%- if clean_substep_url == current_page_url -%}
          {%- assign current_step_index = step_number -%}
        {%- endif -%}
      {%- endfor -%}
    {%- endif -%}
  {%- endfor -%}

  {%- comment -%}If we found the current step in this scenario, find the next step{%- endcomment -%}
  {%- if current_step_index > 0 -%}
    {%- assign next_step_index = current_step_index | plus: 1 -%}
    {%- assign step_number = 0 -%}

    {%- for step in scenario.steps -%}
      {%- assign step_number = step_number | plus: 1 -%}
      {%- if step_number == next_step_index -%}
        {%- capture next_phase_data -%}{{ step.url }}|{{ step.title }}|{{ scenario.title }}|{{ step_number }}{%- endcapture -%}
        {%- assign next_phase_info = next_phase_info | push: next_phase_data -%}
        {%- break -%}
      {%- endif -%}
    {%- endfor -%}
  {%- endif -%}
{%- endfor -%}

{%- comment -%}Remove duplicates from next_phase_info — dedup by URL so when every scenario goes to the same next phase, we show one link instead of repeating it per scenario{%- endcomment -%}
{%- assign unique_next_phases = '' | split: '' -%}
{%- for phase_data in next_phase_info -%}
  {%- assign phase_parts = phase_data | split: '|' -%}
  {%- assign phase_url = phase_parts[0] -%}
  {%- assign is_duplicate = false -%}

  {%- for unique_phase_data in unique_next_phases -%}
    {%- assign unique_parts = unique_phase_data | split: '|' -%}
    {%- if unique_parts[0] == phase_url -%}
      {%- assign is_duplicate = true -%}
      {%- break -%}
    {%- endif -%}
  {%- endfor -%}

  {%- unless is_duplicate -%}
    {%- assign unique_next_phases = unique_next_phases | push: phase_data -%}
  {%- endunless -%}
{%- endfor -%}


{%- comment -%}Display Previous Phase section{%- endcomment -%}
{%- if unique_prev_phases.size > 0 %}

## Previous phase

{%- if unique_prev_phases.size == 1 -%}
{%- assign phase_data = unique_prev_phases[0] -%}
{%- assign phase_parts = phase_data | split: '|' %}
{%- assign clean_prev_url = phase_parts[0] | replace: '{{site.url}}{{site.baseurl}}', '' %}

The previous phase in the migration process was:

**[{{ phase_parts[1] }}]({{ site.url }}{{ site.baseurl }}{{ clean_prev_url }})**

{%- else %}

The previous phase depends on your migration scenario:

{% for phase_data in unique_prev_phases -%}
{%- assign phase_parts = phase_data | split: '|' %}
{%- assign clean_prev_url = phase_parts[0] | replace: '{{site.url}}{{site.baseurl}}', '' -%}
- **{{ phase_parts[2] }}**: [{{ phase_parts[1] }}]({{ site.url }}{{ site.baseurl }}{{ clean_prev_url }})
{% endfor %}
{%- endif %}
{%- endif %}

{%- comment -%}Display Next Phase section{%- endcomment -%}
{%- if unique_next_phases.size > 0 %}

## Next phase

{%- if unique_next_phases.size == 1 -%}
{%- assign phase_data = unique_next_phases[0] -%}
{%- assign phase_parts = phase_data | split: '|' %}
{%- assign clean_next_url = phase_parts[0] | replace: '{{site.url}}{{site.baseurl}}', '' %}

The next phase in the migration process is:

**[{{ phase_parts[1] }}]({{ site.url }}{{ site.baseurl }}{{ clean_next_url }})**

For a complete overview of all migration phases, see [Migration phases]({{ site.url }}{{ site.baseurl }}/migration-assistant/migration-phases/).

{%- else %}

The next phase depends on your migration scenario:

{% for phase_data in unique_next_phases -%}
{%- assign phase_parts = phase_data | split: '|' %}
{%- assign clean_next_url = phase_parts[0] | replace: '{{site.url}}{{site.baseurl}}', '' -%}
- **{{ phase_parts[2] }}**: [{{ phase_parts[1] }}]({{ site.url }}{{ site.baseurl }}{{ clean_next_url }})
{% endfor %}

For a complete overview of all migration phases, see [Migration phases]({{ site.url }}{{ site.baseurl }}/migration-assistant/migration-phases/).

{%- endif %}
{%- endif %}

{% assign scenarios = include.scenarios %}

{% for scenario in scenarios %}
<div class="scenario-container" id="scenario-{{ forloop.index }}">
  <div class="scenario-title">{{ scenario.title }}</div>

  <ol>
    {% for step in scenario.steps %}
      <li>
        {% if step.url %}
          {% assign clean_step_url = step.url | replace: '{{site.url}}{{site.baseurl}}', '' %}
          <a href="{{ site.url }}{{ site.baseurl }}{{ clean_step_url }}">{{ step.title }}</a>
        {% else %}
          {{ step.title }}
        {% endif %}

        {% if step.substeps %}
          <ul>
            {% for substep in step.substeps %}
              <li>
                {% if substep.url %}
                  {% assign clean_substep_url = substep.url | replace: '{{site.url}}{{site.baseurl}}', '' %}
                  <a href="{{ site.url }}{{ site.baseurl }}{{ clean_substep_url }}">{{ substep.title }}</a>
                {% else %}
                  {{ substep.title }}
                {% endif %}
              </li>
            {% endfor %}
          </ul>
        {% endif %}
      </li>
    {% endfor %}
  </ol>
</div>
{% endfor %}

{%- comment -%}
    The values of `title` and `nav_order` can be numbers or strings.
    Jekyll gives build failures when sorting on mixtures of different types,
    so numbers and strings need to be sorted separately.

    Here, numbers are sorted by their values, and come before all strings.
    An omitted `nav_order` value is equivalent to the page's `title` value
    (except that a numerical `title` value is treated as a string).

    The case-sensitivity of string sorting is determined by `site.nav_sort`.
{%- endcomment -%}

{%- comment -%}Pre-compute and cache page lists to avoid repeated filtering{%- endcomment -%}
{%- assign titled_pages = include.pages | where_exp:"item", "item.title != nil" -%}

{%- comment -%}Separate pages by nav_order type for efficient sorting{%- endcomment -%}
{%- assign string_ordered_pages = titled_pages | where_exp:"item", "item.nav_order == nil" -%}
{%- assign nav_ordered_pages = titled_pages | where_exp:"item", "item.nav_order != nil" -%}

{%- comment -%}Group nav_ordered_pages by type (number vs string){%- endcomment -%}
{%- assign nav_ordered_groups = nav_ordered_pages | group_by_exp:"item", "item.nav_order | jsonify | slice: 0" -%}
{%- assign number_ordered_pages = "" | split:"X" -%}
{%- for group in nav_ordered_groups -%}
  {%- if group.name == '"' -%}
    {%- assign string_ordered_pages = string_ordered_pages | concat: group.items -%}
  {%- else -%}
    {%- assign number_ordered_pages = number_ordered_pages | concat: group.items -%}
  {%- endif -%}
{%- endfor -%}

{%- assign sorted_number_ordered_pages = number_ordered_pages | sort:"nav_order" -%}

{%- comment -%}Sort string pages{%- endcomment -%}
{%- assign string_ordered_groups = string_ordered_pages | group_by_exp:"item", "item.nav_order | default: item.title | append:''" -%}
{%- if site.nav_sort == 'case_insensitive' -%}
  {%- assign sorted_string_ordered_groups = string_ordered_groups | sort_natural:"name" -%}
{%- else -%}
  {%- assign sorted_string_ordered_groups = string_ordered_groups | sort:"name" -%}
{%- endif -%}
{%- assign sorted_string_ordered_pages = "" | split:"X" -%}
{%- for group in sorted_string_ordered_groups -%}
  {%- assign sorted_string_ordered_pages = sorted_string_ordered_pages | concat: group.items -%}
{%- endfor -%}

{%- assign pages_list = sorted_number_ordered_pages | concat: sorted_string_ordered_pages -%}

{%- comment -%}Pre-compute current page context for faster lookups{%- endcomment -%}
{%- assign current_collection = page.collection -%}
{%- assign current_url = page.url -%}
{%- assign current_parent = page.parent -%}
{%- assign current_grand_parent = page.grand_parent -%}
{%- assign current_great_grand_parent = page.great_grand_parent -%}

<ul 
  role="tree" 
  aria-expanded="{{ include.expanded | default: 'false' }}"
  class="nav-list"
{%- if include.owned_tree_id -%}id="{{ include.owned_tree_id }}"{%- endif  -%}
>
  {%- for node in pages_list -%}
    {%- unless node.parent or node.nav_exclude -%}
      {%- assign nested_owned_tree_id = include.owned_tree_id | append: "_" | append: forloop.index | append: "_" | append: node.title | append: "_navitems" | replace: " ", "_" -%}

      {%- comment -%}Optimized ancestor checking{%- endcomment -%}
      {%- assign is_ancestor = false -%}
      {%- if current_collection == include.key -%}
        {%- if current_url == node.url or current_parent == node.title or current_grand_parent == node.title or current_great_grand_parent == node.title -%}
          {%- assign is_ancestor = true -%}
        {%- endif -%}
      {%- endif -%}
      <li role="none" class="nav-list-item{% if is_ancestor %} active{% endif %}">
        {%- if node.has_children -%}
          <a
            role="treeitem"
            aria-owns="{{ nested_owned_tree_id }}"
            {%- if current_url == node.url -%}aria-current="page"{%- endif -%}
            href="#" 
            class="nav-list-expander"
          ><svg viewBox="0 0 24 24"><use xlink:href="#svg-arrow-right"></use></svg></a>
        {%- endif -%}

        <a
          role="treeitem"
          {%- if node.has_children -%}aria-owns="{{ nested_owned_tree_id }}"{%- endif -%}
          {%- if current_url == node.url -%}aria-current="page"{%- endif -%}
          href="{{ node.url | absolute_url }}" 
          class="nav-list-link{% if current_url == node.url %} active{% endif %}"
        >{{ node.title }}</a>
        {%- if node.has_children -%}
          {%- comment -%}Pre-filter children to avoid repeated filtering{%- endcomment -%}
          {%- assign children_list = pages_list | where: "parent", node.title -%}
          <ul role="tree" class="nav-list" id="{{ nested_owned_tree_id }}">
          {%- for child in children_list -%}
            {%- unless child.nav_exclude -%}
            {%- assign child_is_ancestor = false -%}
            {%- if current_url == child.url or current_parent == child.title or current_grand_parent == child.title or current_great_grand_parent == child.title -%}
              {%- assign child_is_ancestor = true -%}
            {%- endif -%}
            <li role="none" class="nav-list-item{% if child_is_ancestor %} active{% endif %}">
              {%- if child.has_children -%}
                {%- assign nested_nested_owned_tree_id = nested_owned_tree_id | append: "_" | append: forloop.index | append: "_" | append: child.title | append: "_navitems" | replace: " ", "_" -%}
                <a
                  role="treeitem"
                  aria-owns="{{ nested_nested_owned_tree_id }}"
                  {%- if current_url == child.url -%}aria-current="page"{%- endif -%}
                  href="#" 
                  class="nav-list-expander"
                ><svg viewBox="0 0 24 24"><use xlink:href="#svg-arrow-right"></use></svg></a>
              {%- endif -%}
              <a
                role="treeitem"
                {%- if child.has_children -%}aria-owns="{{ nested_nested_owned_tree_id }}"{%- endif -%}
                {%- if current_url == child.url -%}aria-current="page"{%- endif -%}
