        "_score": 1,
        "_source": {
          "date": "2022-06-15T10:12:52.382719622Z"
        }
      }
    ]
  }
}
```

When querying documents with `date_nanos` fields, you can use `fields` or `docvalue_fields`:

```json
GET testindex/_search
{
  "fields": ["date"]
}
```
{% include copy-curl.html %}

```json
GET testindex/_search
{
  "docvalue_fields" : [
    {
      "field" : "date"
    }
  ]
}
```
{% include copy-curl.html %}

